<template>
<div  class="login-container"  >
    <!-- 语言切换按钮 -->
    <div class="lang-switcher">
      <span
        :class="{ active: $i18n.locale === 'zh' }"
        @click="switchLocale('zh')">简中</span>
      <span class="sep">/</span>
      <span
        :class="{ active: $i18n.locale === 'en' }"
        @click="switchLocale('en')">EN</span>
    </div>

    <el-form ref="form" :model="form" :rules="rules" class="login-page">
      <h2 class="title" style="margin-bottom: 20px">{{ $t('login.title') }}</h2>
      <el-form-item prop="username" >
        <el-input v-model="form.username" :placeholder="$t('login.username')" clearable>
          <template #prefix>
            <el-icon class="el-input__icon"><User /></el-icon>
          </template>
        </el-input>
      </el-form-item>
      <el-form-item prop="password">
        <el-input v-model="form.password" :placeholder="$t('login.password')" clearable show-password>
          <template #prefix>
            <el-icon class="el-input__icon"><Lock /></el-icon>
          </template>
        </el-input>
      </el-form-item>
      <el-form-item>
        <div style="display: flex; justify-content: space-between; align-items: center;">
          <el-input v-model="form.validCode" style="width: 60%;" :placeholder="$t('login.captchaPlaceholder')"></el-input>
          <ValidCode @input="createValidCode" style="flex-shrink: 0;"/>
        </div>
      </el-form-item>
      <el-form-item >
        <el-button type="primary" style="width: 100%" @click="login">{{ $t('login.loginBtn') }}</el-button>
      </el-form-item>
      <el-form-item><el-button type="text" @click="$router.push('/register')">{{ $t('login.registerLink') }}</el-button></el-form-item>
    </el-form>
</div>

</template>

<script>
import request from "../utils/request";
import {ElMessage} from "element-plus";
import ValidCode from "../components/Validate";

export default {
  name: "Login",
  components:{
    ValidCode
  },
  mounted() {
    document.documentElement.classList.remove('dark')
  },
  data() {
    return {
      validCode: '',
      form: {},
    }
  },
  computed: {
    rules() {
      return {
        username: [{
          required: true,
          message: this.$t('login.usernameRequired'),
          trigger: 'blur',
        }],
        password: [{
          required: true,
          message: this.$t('login.passwordRequired'),
          trigger: 'blur',
        }]
      }
    }
  },
  methods: {
    createValidCode(data){
      this.validCode = data
    },
    switchLocale(locale) {
      this.$i18n.locale = locale
      localStorage.setItem('locale', locale)
    },
    login(){
      this.$refs['form'].validate((valid) => {
        if (valid) {
          if (!this.form.validCode) {
            ElMessage.error(this.$t('login.captchaRequired'))
            return
          }
          if(this.form.validCode.toLowerCase() !== this.validCode.toLowerCase()) {
            ElMessage.error(this.$t('login.captchaError'))
            return
          }

          request.post("user/login", this.form).then(res => {
            if (res.code == 0) {
              ElMessage.success(this.$t('login.loginSuccess'))
              sessionStorage.setItem("user",JSON.stringify(res.data))
              this.$router.push("/dashboard")
            } else {
              ElMessage.error(res.msg)
            }
          })
        }
      })

    }
  }
}

</script>

