  position: absolute;
  top: 20px;
  right: 30px;
  font-size: 0.875rem;
  color: #606266;
  cursor: pointer;
  user-select: none;
  z-index: 10;
}
.lang-switcher .sep {
  margin: 0 4px;
  color: #c0c4cc;
  cursor: default;
}
.lang-switcher .active {
  color: #409eff;
  font-weight: 600;
}
